"""Apply the tested read-side canonical alias call only."""
from pathlib import Path
import base64,hashlib,subprocess
raw=base64.b64decode('',validate=True)
assert hashlib.sha256(raw).hexdigest()=='8fa0c91249d0b49a8f2b662341f44370cb49be5beb3ff25472c147ebfd70556d'
p=Path('/tmp/public-alias.patch');p.write_bytes(raw)
subprocess.run(['git','apply','--check',str(p)],check=True)
subprocess.run(['git','apply',str(p)],check=True)
